CREATE TABLE IF NOT EXISTS `models` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `filename` TEXT NOT NULL, `architecture` TEXT NOT NULL, `quantization` TEXT NOT NULL, `parameterCount` TEXT NOT NULL, `contextLength` INTEGER NOT NULL, `fileSizeMb` INTEGER NOT NULL, `ramRequiredMb` INTEGER NOT NULL, `isInstalled` INTEGER NOT NULL, `isActive` INTEGER NOT NULL, `isCustom` INTEGER NOT NULL, `description` TEXT NOT NULL, `capabilities` TEXT NOT NULL, `downloadUrl` TEXT, `downloadState` TEXT NOT NULL, `downloadProgress` REAL NOT NULL, `downloadSpeedMbps` REAL NOT NULL, `localFilePath` TEXT, `versionTag` TEXT NOT NULL, `speedScoreTokSec` REAL NOT NULL, `recommendedTier` TEXT NOT NULL, `huggingFaceRepo` TEXT, `sha256Checksum` TEXT, `isChecksumVerified` INTEGER NOT NULL, `checksumVerificationStatus` TEXT NOT NULL, `isBaseModel` INTEGER NOT NULL, `lastUsedTimestamp` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `ipc_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `callingPackage` TEXT NOT NULL, `callingUid` INTEGER NOT NULL, `requestType` TEXT NOT NULL, `promptPreview` TEXT NOT NULL, `responsePreview` TEXT NOT NULL, `latencyMs` INTEGER NOT NULL, `tokensPerSecond` REAL NOT NULL, `totalTokens` INTEGER NOT NULL, `timestamp` INTEGER NOT NULL, `status` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `client_policies` (`packageName` TEXT NOT NULL, `appName` TEXT NOT NULL, `isWhitelisted` INTEGER NOT NULL, `autoApprove` INTEGER NOT NULL, `totalRequests` INTEGER NOT NULL, `lastAccessTimestamp` INTEGER NOT NULL, `rateLimitPerMin` INTEGER NOT NULL, `isBlocked` INTEGER NOT NULL, `allowInference` INTEGER NOT NULL, `allowReadMemory` INTEGER NOT NULL, `allowWriteMemory` INTEGER NOT NULL, `allowStructuredJson` INTEGER NOT NULL, `customSystemPrompt` TEXT NOT NULL, `allowedMemoryCategories` TEXT NOT NULL, PRIMARY KEY(`packageName`));
CREATE TABLE IF NOT EXISTS `chat_messages` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `role` TEXT NOT NULL, `content` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `latencyMs` INTEGER NOT NULL, `tokensPerSec` REAL NOT NULL, `promptTokens` INTEGER NOT NULL, `completionTokens` INTEGER NOT NULL, `modelName` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `memory_snippets` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `content` TEXT NOT NULL, `category` TEXT NOT NULL, `sourceApp` TEXT NOT NULL, `isActive` INTEGER NOT NULL, `timestamp` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `hardware_performance_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `modelName` TEXT NOT NULL, `filename` TEXT NOT NULL, `architecture` TEXT NOT NULL, `quantization` TEXT NOT NULL, `parameterCount` TEXT NOT NULL, `tokensPerSecond` REAL NOT NULL, `promptProcessingTokSec` REAL NOT NULL, `timeToFirstTokenMs` INTEGER NOT NULL, `peakRamMb` INTEGER NOT NULL, `ramAvailableAtTestMb` INTEGER NOT NULL, `batteryTemperatureC` REAL NOT NULL, `thermalState` TEXT NOT NULL, `threadCount` INTEGER NOT NULL, `gpuLayers` INTEGER NOT NULL, `deviceModel` TEXT NOT NULL, `chipsetAbi` TEXT NOT NULL, `testType` TEXT NOT NULL, `efficiencyScore` REAL NOT NULL, `timestamp` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
